const TIME_LIMIT: int = 2576;
const OPENING_BUFFER: int = 120;
const TH15_FIREBALL_PURPLE: int = 768;

// Only source reaction-mark 0 bullets receive this rule. Other marks must not bind it.
// Globals 16..21 publish three moon centers at 1/32 px precision.
// No source fixed lifetime: outside the three discs keep the bullet alive until normal
// screen cleanup; inside any disc set life=1. No per-bullet task/pool is needed.
xformdef MARK_ZERO {
again:
    @1 set_life(at_effect(1 + 65534 * (global(22) == 0 || (
        dist($self_x - (global(16) as fx / 32), $self_y - (global(17) as fx / 32)) > 64fx &&
        dist($self_x - (global(18) as fx / 32), $self_y - (global(19) as fx / 32)) > 64fx &&
        dist($self_x - (global(20) as fx / 32), $self_y - (global(21) as fx / 32)) > 64fx))));
    goto again;
}

// st05bs:1440-1467. ABS circle centered on birth FINAL (0,192), plus REL circle.
// Both radius ramps are source mode1 (quadratic IN); REL omega ramps 5->2 deg/frame.
async sub moon(initial: int, slot: int) {
    set_invuln(65535);
    set_hurtbox(54fx);
    set_hitbox(48fx);
    // Source flag8988 has no0x2/0x20 body-disable bit; retain radius48.
    var theta: fx = initial as fx / 65536 * 360;
    var t: int = 0;
    var until_shot: int = 140;
    var rank: int = global(GVAR_RANK);
    var ways: int = 23;
    var speed: fx = 0.8fx;
    var start: int = 120;
    var goal: int = 30;
    if rank == 0 { ways = 18; goal = 60; }
    if rank == 2 { speed = 1.2fx; goal = 25; }
    if rank == 3 { ways = 26; speed = 1.2fx; start = 60; goal = 25; }
    sh_reset(0);
    sh_sprite(0, TH15_FIREBALL_PURPLE, 0); // source type26,color0
    sh_count(0, ways, 1);
    sh_ring(0, 1);
    sh_aim(0, 1); // etAim2, one speed layer
    sh_angle(0, 0deg, 10deg);
    sh_speed(0, speed, 0fx);
    sh_dist(0, 80fx - speed*4); // st05bs:1497 ANIM retreat plus1499 etDist.
    sh_xform(0, MARK_ZERO);
    while t < 2130 {
        // Source F(k), then arrange F(k+1) after firing. No unconditional teleport.
        set_global(slot, ($self_x * 32) as int);
        set_global(slot+1, ($self_y * 32) as int);
        if until_shot == 0 {
            sh_fire(0);
            // st05bs:1518 stack [goal,start]: floatTime starts120(60 L), ends60/30/25.
            var elapsed: int = t-140;
            if elapsed > 1320 { elapsed = 1320; }
            var interval: fx = start as fx + ((goal-start) as fx)*elapsed/1320;
            until_shot = interval as int;
        }
        t = t+1;
        var rel_k: int = t;
        if rel_k > 60 { rel_k = 60; }
        var abs_k: int = t;
        if abs_k > 240 { abs_k = 240; }
        var u: fx = rel_k as fx / 60;
        var v: fx = abs_k as fx / 240;
        var rr: fx = 140fx*u*u;
        var ar: fx = 140fx*v*v;
        // fx holds degrees for sub-BAM accumulation; reduce phase every turn.
        theta = theta + (5fx - 3fx*u*u);
        if theta >= 180fx { theta = theta-360fx; }
        var rel_angle: angle = ((theta/360*65536) as int) as angle;
        var abs_angle: angle = (16384 + (-t*65536)/450) as angle;
        var nx: fx = ar*cos(abs_angle) + rr*cos(rel_angle);
        var ny: fx = 192fx + ar*sin(abs_angle) + rr*sin(rel_angle);
        move_vel_xy(0, nx-$self_x, ny-$self_y, EASE_LINEAR);
        until_shot = until_shot-1;
        wait(1);
    }
}

// Boss5:530-569 then BossCard5:1366-1438. Source entry t0 maps to card120
// plus task-start scheduling; +4,+160,+4,+90 puts moon creation at source258.
async sub boss() {
    set_invuln(65535);
    set_hurtbox(20fx);
    set_hitbox(24fx);
    // BossCard5 flag3 includes source bit2 (body off).
    set_enemy_flag(ENEMY_NO_BODY, 1);
    clear_bullets();
    wait(2);
    wait(2);
    kill_all_enemies(KILL_SILENT);
    clear_bullets();
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    wait(160);
    clear_bullets();
    wait(2);
    wait(2);
    kill_all_enemies(KILL_SILENT);
    clear_bullets();
    move_vel_xy(0, 0fx, 0fx, EASE_LINEAR);
    move_to(60, 0fx, 192fx, EASE_QUAD_OUT);
    wait(90);
    // Initialize all centers before any bullet can evaluate MARK_ZERO.
    for i in 16..22 { set_global(i, 0); }
    set_global(22, 1);
    set_global(17, 6144); set_global(19, 6144); set_global(21, 6144);
    _ = spawn_enemy($self_x, $self_y, 100, 0, 0, 0, moon(-16384, 16));
    _ = spawn_enemy($self_x, $self_y, 100, 0, 0, 0, moon(5461, 18));
    _ = spawn_enemy($self_x, $self_y, 100, 0, 0, 0, moon(27307, 20));
    wait(2130); // final timerReset at source168, timeout at2388 (2220 later).
    set_global(22, 0); // funcSet2 ends with the moon enemies; tail bullets no longer cancel here.
    kill_all_enemies(KILL_SILENT);
    // BossDead tail: sixty frames of surviving bullets, then etClearAll.
    wait(60);
    clear_bullets();
}
async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 1, 0, 0, 0, boss);
}
async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY + ENEMY_KILLALL_EXEMPT, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}
sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
